import re, subprocess, sys

fams=[]
for line in open('synonyms.txt'):
    ws=[w.strip() for w in line.split(',') if w.strip()]
    if len(ws)>1:
        fams.append(ws)

def write(lines):
    with open('input.tex','w') as f:
        f.write('\n'.join(lines))

def overfull():
    subprocess.run(['pdflatex','-draftmode','-interaction=nonstopmode','main.tex'],
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    log=open('main.log',errors='ignore').read()
    out=[]
    for m in re.finditer(r'Overfull \\hbox \(([\d.]+)pt too wide\) in paragraph at lines (\d+)--(\d+)', log):
        out.append((int(m.group(2)), int(m.group(3)), float(m.group(1))))
    return out

lines=open('input.tex').read().split('\n')

def para_count(paraline, ents):
    return sum(1 for a,b,p in ents if min(a,b)==paraline)

def para_pts(paraline, ents):
    return sum(p for a,b,p in ents if min(a,b)==paraline)

for paraline in [int(x) for x in sys.argv[1:]]:
    idx=paraline-1
    cur=list(lines)
    best=overfull()
    print('para',paraline,'overfull count',para_count(paraline,best),'pts',para_pts(paraline,best), flush=True)
    improved=True
    while improved and para_count(paraline,best)>0:
        improved=False
        text=cur[idx]
        bestc=para_count(paraline,best); bestp=para_pts(paraline,best)
        for fam in fams:
            for word in fam:
                if not re.search(r'\b'+re.escape(word)+r'\b', text):
                    continue
                for syn in fam:
                    if syn==word:
                        continue
                    newtext=re.sub(r'\b'+re.escape(word)+r'\b', syn, text)
                    trial=list(cur); trial[idx]=newtext
                    write(trial)
                    ents=overfull()
                    c=para_count(paraline,ents)
                    p=para_pts(paraline,ents)
                    if (c,p) < (bestc,bestp):
                        bestc,bestp=c,p
                        cur=trial
                        best=ents
                        improved=True
                        print('  took',word,'->',syn,'count',c,'pts',round(p,3), flush=True)
                        write(cur)
                        text=cur[idx]
        if not improved:
            print('  no improvement found; stuck at',bestc, flush=True)
    write(cur)
print('done', flush=True)
EOF
